BEGIN;

INSERT INTO public.questions
  (subject_id, category_id, source_ref, question_text, code, options,
   correct_index, correct_indices, question_type, explanation, explanation_data, initial_wrong_weight)
SELECT s.id, c.id, v.source_ref, v.question_text, v.code, v.options::jsonb,
       v.correct_index, v.correct_indices::jsonb, v.question_type, '', v.explanation_data::jsonb, 1
FROM public.subjects s
JOIN public.categories c ON c.subject_id = s.id
JOIN (VALUES

  ('ap-core-q250', 'データベース方式とデータモデル',
   '論理設計に入る前段階で、業務要件からどんなデータの実体(エンティティ)や実体同士のつながり(関連)があるかを洗い出す作業を何と呼ぶか。',
   NULL::text,
   '["データ分析","データ操作","物理設計","正規化"]',
   0, '[0]', 'single',
   '{"asked":"論理設計に入る前段階で、業務要件からエンティティや関連を洗い出す作業が何と呼ばれるかを問う。","point":"要件からエンティティと関連を洗い出す最初の整理作業ならデータ分析。","kid":"テーブルを作る前に、どんな情報のかたまりがあり、それぞれがどうつながっているかを整理する作業。","eg":"引っ越し前に「何を持っているか、どれとどれを一緒に収納するか」をリストアップする作業に近い。","terms":[["エンティティ","業務の中で扱う情報のひとかたまり(例: 顧客、注文などの実体)"],["データ分析","業務要件からエンティティや関連を洗い出す作業"]],"think":"家を建てる前に「どんな部屋が要るか、部屋同士がどうつながるか」を整理するのと同じで、テーブルを作る前にまず業務の中にどんな情報のかたまり(エンティティ)があり、それらがどう関連しているかを整理する必要がある。この整理作業がデータ分析であり、この結果を後の論理設計(E-R図やテーブル定義)に反映していく。","why_asked":"データベース設計の全体像(データ分析→論理設計→物理設計)のうち最初の工程を、後工程の正規化やSQL操作と混同せず理解しているかを問う。","opt":["正解。業務要件からデータの実体(エンティティ)や実体同士の関連を洗い出す、論理設計の前段階の作業である。","データベースに対してSELECTやUPDATEなどの命令を実行する作業であり、設計の前段階の分析作業ではない。","論理設計で決めたテーブル構造を、実際のDBMS上にどう配置するかを決める作業であり、データ分析より後の工程である。","同じ情報を重複して持たないようテーブルを整理する作業であり、実体や関連を洗い出す分析作業とは異なる。"]}'),

  ('ap-core-q251', 'データベース方式とデータモデル',
   'データベース設計における論理設計と物理設計の違いとして、最も適切なものはどれか。',
   NULL::text,
   '["論理設計は業務の視点でテーブルや列の構造を決め、物理設計はそれをDBMS上でどう実装するか(ファイル配置やインデックス等)を決める。","論理設計はDBMS上のファイル配置やインデックスといった実装方法を決め、物理設計は業務の視点からテーブルの構造を決める。","論理設計と物理設計はどちらも業務の視点だけでテーブルの構造を決める工程であり、扱う対象や視点に違いはない。","論理設計はSQL文を記述してデータを操作する実装の工程であり、物理設計はE-R図を描いて業務要件を整理する工程である。"]',
   0, '[0]', 'single',
   '{"asked":"論理設計と物理設計が、それぞれ何の視点でデータベースを設計する工程かの違いを問う。","point":"業務の視点なら論理設計、DBMS上の実装(ファイル・インデックス)の視点なら物理設計。","kid":"論理設計は間取り図を決める工程、物理設計はその間取りを実際にどう建てるか決める工程。","eg":"論理設計=間取り図、物理設計=実際の配線・配管工事。","terms":[["論理設計","業務の視点でテーブル・列の構造を決める工程"],["物理設計","論理設計をDBMS上でどう格納・実装するか決める工程"]],"think":"家づくりで例えると、論理設計は「どの部屋を何のために使うか」という間取りの決定、物理設計は「実際にどの建材で、どう配管を通すか」という施工レベルの決定にあたる。同じ「設計」でも、論理設計は業務にとっての意味を優先し、物理設計は性能や実装上の制約を優先する、という視点の違いがある。","why_asked":"論理設計と物理設計を同じものとして曖昧に覚えていないか、視点の違い(業務 vs 実装)を理解しているかを問う。","vs":"論理設計はE-R図やテーブル定義という「業務の意味」を扱うのに対し、物理設計はインデックスやファイル配置という「実装の都合」を扱う点で異なる。","opt":["正解。論理設計は業務にとって意味のあるテーブル・列の構造を決め、物理設計はそれをDBMS上でどう格納・アクセスするかを決める。","論理設計と物理設計の説明が逆になっている。業務視点が論理設計、実装視点が物理設計である。","論理設計は業務視点、物理設計は実装視点というように対象範囲が異なる。同じ工程ではない。","論理設計・物理設計はいずれも設計工程であり、SQL文を書く実装作業やE-R図作成そのものを指す言葉ではない。"],"viz":"<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"16\" font-size=\"11\" fill=\"#8892a4\" text-anchor=\"middle\">論理設計と物理設計の視点の違い</text><rect x=\"20\" y=\"40\" width=\"130\" height=\"60\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"85\" y=\"65\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\">論理設計</text><text x=\"85\" y=\"83\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">業務視点で</text><text x=\"85\" y=\"95\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">テーブル構造を決める</text><path d=\"M155 70 L185 70\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#arrow1)\"/><rect x=\"190\" y=\"40\" width=\"130\" height=\"60\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"255\" y=\"65\" font-size=\"12\" fill=\"#e8eaf0\" text-anchor=\"middle\">物理設計</text><text x=\"255\" y=\"83\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">DBMS上の</text><text x=\"255\" y=\"95\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">格納方法を決める</text><text x=\"170\" y=\"130\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">同じテーブルでも物理設計次第で速さが変わる</text></svg>"}'),

  ('ap-core-q252', 'データベース方式とデータモデル',
   'テーブルにインデックスを追加することの一般的な効果として、最も適切なものはどれか。',
   NULL::text,
   '["検索(SELECT)は速くなるが、データの追加・更新(INSERT/UPDATE)はインデックスの更新も必要になり遅くなりやすい。","インデックスを追加すると検索・更新のどちらも一様に速くなり、性能面でのデメリットは特に生じない。","検索(SELECT)は遅くなるが、データの追加・更新(INSERT/UPDATE)はインデックスの影響を受けず速くなる。","インデックスを追加しても、検索・更新のどちらの処理速度にも実質的な影響はほとんど生じない。"]',
   0, '[0]', 'single',
   '{"asked":"インデックスを追加すると検索・更新それぞれの速さがどう変わるかを問う。","point":"インデックスは「検索は速く、更新は遅くなりやすい」というトレードオフを生む。","kid":"インデックスを付けると検索は速くなるが、データを書き換えるたびに索引も直す必要があり更新は遅くなりやすい。","eg":"本の索引は調べ物には便利だが、本文を書き換えるたびに索引ページの見直しも必要になるのと同じ。","terms":[["インデックス","本の索引のように、検索を速くするために用意しておく仕組み"]],"think":"索引(インデックス)は「本の索引」と同じで、目的のページ(データ)をすぐに見つけられるようにする一覧表である。検索するときはこの一覧表を使って一気に絞り込めるので速くなる。しかし本文が更新されるたびに索引の該当ページ番号も直さなければならないのと同じで、データを追加・更新するたびにインデックスも合わせて更新する必要があり、その分だけ書き込みは遅くなりやすい。","why_asked":"インデックスを「付ければ付けるほど良い」と誤解していないか、検索と更新のトレードオフを理解しているかを問う。","opt":["正解。検索時はインデックスを使って絞り込めるので速くなるが、更新時はインデックス自体の更新も必要になるため遅くなりやすい。","検索は速くなるが、更新にインデックスの更新コストがかかるため、更新まで常に速くなるわけではない。","検索と更新の説明が逆になっている。インデックスは検索を速くする代わりに更新を遅くしやすい。","インデックスは検索の速度に影響しないという説明は誤り。検索を高速化するために作る仕組みである。"]}'),

  ('ap-core-q253', 'データベース方式とデータモデル',
   '正規化されたテーブルをあえて崩し、重複を許容してでも1つのテーブルにまとめる設計判断を何と呼ぶか。',
   NULL::text,
   '["非正規化","正規化","インデックス設計","データ分析"]',
   0, '[0]', 'single',
   '{"asked":"検索性能などを優先し、正規化を意図的に崩す設計判断が何と呼ばれるかを問う。","point":"検索性能を優先して意図的に重複を許容する設計判断は非正規化。","kid":"正規化してテーブルを分けすぎると結合(JOIN)が増えて遅くなることがあるので、あえて重複を許してテーブルをまとめ直すことがある。","eg":"別々の引き出しに整理していた道具を、よく一緒に使うからと1つの引き出しにまとめ直すようなもの。多少重複や散らかりは増えるが、取り出しやすくなる。","terms":[["非正規化","検索性能などを優先して、あえて正規化を崩し重複を許容する設計判断"]],"think":"正規化は「同じ情報を重複させない」ことを目指すが、その結果テーブルが増え、検索のたびに複数テーブルを結合(JOIN)する必要が生じ、性能が落ちることがある。そこで、検索性能を優先して、あえて重複を許容し1つのテーブルにまとめ直す判断を行うことがある。これが非正規化であり、正規化の理屈を理解した上で「性能とのトレードオフとして意図的に崩す」という点がポイントになる。","why_asked":"正規化の知識だけで終わらず、性能とのトレードオフとして非正規化という逆方向の判断もあることを理解しているかを問う。","vs":"正規化は重複を無くす方向、非正規化は性能のためにあえて重複を許容する方向で、目的も向きも逆である。","opt":["正解。正規化で分けたテーブルを、検索性能などを優先してあえて重複を許容し統合し直す設計判断である。","同じ情報を重複させないようテーブルを整理する作業であり、あえて重複を許容する非正規化とは逆の考え方である。","検索を高速化するための索引を作る作業であり、テーブル構造そのものを変える非正規化とは異なる。","業務要件からエンティティや関連を洗い出す作業であり、テーブル構造をあえて崩す判断とは異なる。"]}'),

  ('ap-core-q254', 'データベース方式とデータモデル',
   'データベースのパフォーマンス設計を、論理設計とは別に物理設計の段階で行う理由として、最も適切なものはどれか。',
   NULL::text,
   '["データの格納方法やインデックスの持ち方など、実際の処理速度に直結する要素は物理設計で初めて具体的に決まるから。","論理設計の段階で性能はすべて決まってしまうため、物理設計では性能をあらためて考慮する余地がほとんどないから。","性能はアプリケーションのプログラムの書き方だけで決まるものであり、データベースの設計内容とは基本的に無関係だから。","物理設計はあくまで業務要件を整理して定義する工程であり、処理速度などの性能とは直接関係しない工程だから。"]',
   0, '[0]', 'single',
   '{"asked":"パフォーマンス設計を論理設計とは別に物理設計の段階で行う理由を問う。","point":"処理速度に直結する格納方法やインデックスは物理設計で初めて具体化するから、性能はここで作り込む。","kid":"同じテーブル構造でも、実際の格納方法やインデックスの持たせ方次第で速さが大きく変わるので、物理設計の段階で性能を作り込む。","eg":"間取り図(論理設計)が同じでも、実際の配管の太さや配置(物理設計)次第で水の流れる速さが変わるようなもの。","terms":[["物理設計","データの格納方法やインデックスなど実装レベルを決める工程"]],"think":"論理設計では「どんなテーブル・列が必要か」という業務にとっての意味を決めるが、それをディスク上にどう配置し、どんなインデックスを持たせるかまでは決めていない。同じ論理設計でも、物理的な格納方法やインデックスの持たせ方次第で検索・更新の速さは大きく変わる。だからこそ、業務の意味を決める論理設計とは別に、実際の処理速度に直結する部分を物理設計の段階で作り込む必要がある。","why_asked":"性能はプログラムの書き方だけで決まると誤解していないか、物理設計の役割を理解しているかを問う。","opt":["正解。データの格納方法やインデックスの持ち方など、処理速度に直結する要素は物理設計で初めて具体的に決まるため。","論理設計だけで性能がすべて決まるという説明は誤り。物理設計での格納方法やインデックスの選び方も性能に大きく影響する。","性能はプログラムの書き方だけで決まるという説明は誤り。データベースの物理設計も処理速度に大きく影響する。","物理設計は業務要件を決める工程という説明は誤り。業務要件を決めるのは論理設計より前の要件定義・データ分析の工程である。"]}'),

  ('ap-core-q255', 'データベース方式とデータモデル',
   'データベース設計の一連の流れとして、最も適切な順序はどれか。',
   NULL::text,
   '["データ分析でエンティティ・関連を洗い出し、論理設計(E-R図)でテーブル構造を決め、物理設計で格納方法を決めるという順序で進む。","物理設計で格納方法を決めた後にデータ分析でエンティティを洗い出し、最後に論理設計でテーブル構造を決めるという順序で進む。","論理設計でテーブル構造を決めた後にデータ分析でエンティティを洗い出し、最後に物理設計で格納方法を決めるという順序で進む。","データ分析と物理設計はどちらも同じ工程であり、論理設計だけが独立した別工程として存在する。"]',
   0, '[0]', 'single',
   '{"asked":"データベース設計がデータ分析・論理設計・物理設計のどの順序で進むかを問う。","point":"抽象(データ分析)→業務構造(論理設計)→実装(物理設計)という段階的な順序で進む。","kid":"データベース設計は「業務の中身を整理する→テーブル構造を決める→実装方法を決める」という順番で進む。","eg":"引っ越し先の持ち物整理(データ分析)→間取り図に合わせて配置を決める(論理設計)→実際に棚や収納の中身を詰める(物理設計)、という順番に近い。","terms":[["データ分析","エンティティ・関連の洗い出し"],["論理設計","業務視点のテーブル構造決定"],["物理設計","実装レベルの格納方法決定"]],"think":"まず業務の中にどんな情報のかたまり(エンティティ)とそのつながり(関連)があるかを洗い出す(データ分析)。次に、その結果をE-R図などに落とし込み、業務にとって意味のあるテーブル・列の構造を決める(論理設計)。最後に、そのテーブル構造を実際のDBMS上でどう格納し、どんなインデックスを持たせるかを決める(物理設計)。この順序は、抽象的な業務の理解から具体的な実装へと段階的に詰めていく流れになっている。","why_asked":"データベース設計の3工程(データ分析→論理設計→物理設計)の順序関係を正しく理解しているかを問う。","opt":["正解。データ分析でエンティティ・関連を洗い出し、論理設計でテーブル構造を決め、物理設計で格納方法を決めるという段階的な順序になる。","物理設計を最初に行うという順序は誤り。実装方法を決める物理設計は、業務構造を決めた後に行う工程である。","論理設計を最初に行うという順序は誤り。テーブル構造を決める前に、まずどんなエンティティがあるかをデータ分析で洗い出す必要がある。","データ分析と物理設計は異なる工程である。データ分析は業務の理解、物理設計は実装方法の決定という別々の役割を持つ。"],"viz":"<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arrow2\" markerWidth=\"8\" markerHeight=\"8\" refX=\"4\" refY=\"4\" orient=\"auto\"><path d=\"M0,0 L8,4 L0,8 z\" fill=\"#60a5fa\"/></marker></defs><text x=\"170\" y=\"16\" font-size=\"11\" fill=\"#8892a4\" text-anchor=\"middle\">データベース設計の流れ</text><rect x=\"10\" y=\"55\" width=\"90\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#3b82f6\" stroke-width=\"1.5\"/><text x=\"55\" y=\"75\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">データ分析</text><text x=\"55\" y=\"92\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">実体・関連の</text><text x=\"55\" y=\"102\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">洗い出し</text><path d=\"M104 80 L128 80\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#arrow2)\"/><rect x=\"132\" y=\"55\" width=\"90\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"177\" y=\"75\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">論理設計</text><text x=\"177\" y=\"92\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">テーブル構造</text><text x=\"177\" y=\"102\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">を決める</text><path d=\"M226 80 L250 80\" stroke=\"#60a5fa\" stroke-width=\"1.5\" marker-end=\"url(#arrow2)\"/><rect x=\"252\" y=\"55\" width=\"82\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.5\"/><text x=\"293\" y=\"75\" font-size=\"10.5\" fill=\"#e8eaf0\" text-anchor=\"middle\">物理設計</text><text x=\"293\" y=\"92\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">格納方法を</text><text x=\"293\" y=\"102\" font-size=\"9\" fill=\"#8892a4\" text-anchor=\"middle\">決める</text><text x=\"170\" y=\"130\" font-size=\"9.5\" fill=\"#8892a4\" text-anchor=\"middle\">抽象的な業務理解から具体的な実装へ段階的に詰める</text></svg>"}')

) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'ap-core'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
